window.openCudiAiWithQuery = function(query) {
    document.querySelectorAll('.search-results-dropdown').forEach(d => d.style.display = 'none');
    if (typeof CudiAI !== 'undefined') {
        if (!CudiAI.isOpen && typeof CudiAI.open === 'function') {
            CudiAI.open();
        } else if (!CudiAI.isOpen && typeof CudiAI.toggle === 'function') {
            CudiAI.toggle();
        }
        if (query) {
            setTimeout(() => {
                if (typeof CudiAI.handleSuggestion === 'function') {
                    CudiAI.handleSuggestion(query);
                } else {
                    const input = document.getElementById('ai-input');
                    if (input) {
                        input.value = query;
                        if (typeof CudiAI.sendMessage === 'function') CudiAI.sendMessage();
                    }
                }
            }, 300);
        }
    } else {
        const trigger = document.getElementById('cudi-ai-trigger') || document.querySelector('.cudi-ai-toggle-btn');
        if (trigger) trigger.click();
    }
};
